import sys
data = sys.stdin.read().split()
n = int(data[0])
pts = sorted({(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)})      # sorted, duplicates removed

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

if len(pts) == 1:
    print(1, 0)
else:
    # Andrew's monotone chain: build the lower hull left to right, then the upper hull right to left.
    # Popping while cross <= 0 also removes points that merely lie on an edge, so only true corners remain.
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    hull = lower[:-1] + upper[:-1]                    # each chain's last point is the other chain's first
    area2 = 0
    for i in range(len(hull)):
        x1, y1 = hull[i]
        x2, y2 = hull[(i + 1) % len(hull)]
        area2 += x1 * y2 - x2 * y1
    print(len(hull), abs(area2))

