import java.io.*;
import java.util.*;

public class Main {
    static long cross(long[] o, long[] a, long[] b) {
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        long[][] all = new long[n][2];
        for (int i = 0; i < n; i++) {
            in.nextToken(); all[i][0] = (long) in.nval;
            in.nextToken(); all[i][1] = (long) in.nval;
        }
        Arrays.sort(all, (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
        ArrayList<long[]> pts = new ArrayList<>();
        for (long[] p : all)
            if (pts.isEmpty() || pts.get(pts.size() - 1)[0] != p[0] || pts.get(pts.size() - 1)[1] != p[1]) pts.add(p);
        if (pts.size() == 1) { System.out.println("1 0"); return; }
        ArrayList<long[]> lower = new ArrayList<>(), upper = new ArrayList<>();
        for (long[] p : pts) {
            while (lower.size() >= 2 && cross(lower.get(lower.size() - 2), lower.get(lower.size() - 1), p) <= 0)
                lower.remove(lower.size() - 1);
            lower.add(p);
        }
        for (int i = pts.size() - 1; i >= 0; i--) {
            long[] p = pts.get(i);
            while (upper.size() >= 2 && cross(upper.get(upper.size() - 2), upper.get(upper.size() - 1), p) <= 0)
                upper.remove(upper.size() - 1);
            upper.add(p);
        }
        ArrayList<long[]> hull = new ArrayList<>(lower.subList(0, lower.size() - 1));
        hull.addAll(upper.subList(0, upper.size() - 1));
        long area2 = 0;
        for (int i = 0; i < hull.size(); i++) {
            long[] a = hull.get(i), b = hull.get((i + 1) % hull.size());
            area2 += a[0] * b[1] - b[0] * a[1];
        }
        System.out.println(hull.size() + " " + Math.abs(area2));
    }
}

