#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;

ll cross(const P& o, const P& a, const P& b) {
    return (a.first - o.first) * (b.second - o.second) - (a.second - o.second) * (b.first - o.first);
}
int main() {
    int n;
    scanf("%d", &n);
    vector<P> pts(n);
    for (auto& p : pts) scanf("%lld %lld", &p.first, &p.second);
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    if (pts.size() == 1) { puts("1 0"); return 0; }
    vector<P> lower, upper;
    for (const P& p : pts) {
        while (lower.size() >= 2 && cross(lower[lower.size() - 2], lower.back(), p) <= 0) lower.pop_back();
        lower.push_back(p);
    }
    for (int i = (int)pts.size() - 1; i >= 0; i--) {
        const P& p = pts[i];
        while (upper.size() >= 2 && cross(upper[upper.size() - 2], upper.back(), p) <= 0) upper.pop_back();
        upper.push_back(p);
    }
    lower.pop_back();
    upper.pop_back();
    vector<P> hull = lower;
    hull.insert(hull.end(), upper.begin(), upper.end());
    ll area2 = 0;
    for (size_t i = 0; i < hull.size(); i++) {
        const P& a = hull[i];
        const P& b = hull[(i + 1) % hull.size()];
        area2 += a.first * b.second - b.first * a.second;
    }
    printf("%d %lld\n", (int)hull.size(), llabs(area2));
    return 0;
}
